use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
pub(crate) fn fixture()->SemioAudioSnapshot { let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap(); SemioAudioSnapshot {schema:f["schema"].as_str().unwrap().into(),sample_rate:f["sampleRate"].as_u64().unwrap() as u32,format:SemioAudioFormat::Float64,channels:f["channels"].as_array().unwrap().iter().map(|samples|SemioAudioChannel{samples:samples.as_array().unwrap().iter().map(|bits|f32::from_bits(bits.as_u64().unwrap() as u32)).collect()}).collect(),tags:f["tags"].as_array().unwrap().iter().map(|tag|SemioAudioTag{key:tag[0].as_str().unwrap().into(),value:tag[1].as_str().unwrap().into()}).collect()} }
fn project(value:&SemioAudioSnapshot)->SqliteDatabase {value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioAudioSnapshot, semio_framework_value::ValueError>{SemioAudioSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_audio_preserves_all_ieee754_sample_bits_and_native_formats(){let original=fixture();let bytes=export_sqlite_database(&project(&original),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let value=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(<SemioAudioSnapshot as store::ArtifactPack>::encode_pack(&value),<SemioAudioSnapshot as store::ArtifactPack>::encode_pack(&original));for (a,b)in value.channels.iter().zip(&original.channels){assert_eq!(a.samples.iter().map(|n|n.to_bits()).collect::<Vec<_>>(),b.samples.iter().map(|n|n.to_bits()).collect::<Vec<_>>());}for format in [SemioAudioFormat::Pcm8,SemioAudioFormat::Pcm16,SemioAudioFormat::Pcm24,SemioAudioFormat::Pcm32,SemioAudioFormat::Float32,SemioAudioFormat::Float64]{let mut snapshot=SemioAudioSnapshot::default();snapshot.format=format;assert_eq!(restore(&project(&snapshot)).unwrap(),snapshot);}}
#[test]
fn sqlite_snapshot_semio_audio_validates_sample_shape_ownership_ordinals_and_limits(){let original=project(&fixture());for change in 0..4 {let mut db=original.clone();match change{0=>db.table_mut("semio_audio_sample").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_audio_sample").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_audio_sample").unwrap().rows[0].values[3]=SqliteValue::Real(1.0),_=>db.table_mut("semio_audio_sample").unwrap().rows[0].values[4]=SqliteValue::Integer(-1)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioAudioSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_audio_independent_sample_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT value FROM semio_audio_sample WHERE channel_id=1 ORDER BY ordinal').all().map(r=>r.value).join(',')!=='0,0,1,-1')throw Error('samples');db.query('UPDATE semio_audio_sample SET value=0.5,ieee754_bits=1056964608 WHERE channel_id=1 AND ordinal=0').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored.channels[0].samples[0].to_bits(),0.5f32.to_bits());}

